def bf(planet1, planet2):
    planets_order = {
        "Mercury": 1,
        "Venus": 2,
        "Earth": 3,
        "Mars": 4,
        "Jupiter": 5,
        "Saturn": 6,
        "Uranus": 7,
        "Neptune": 8
    }

    planets_between = []

    if planet1 not in planets_order or planet2 not in planets_order:
        return ()

    start = min(planets_order[planet1], planets_order[planet2])
    end = max(planets_order[planet1], planets_order[planet2])

    for planet, order in planets_order.items():
        if start < order < end:
            planets_between.append(planet)

    return tuple(sorted(planets_between, key=lambda x: planets_order[x]))

