def rolling_max(numbers: List[int]) -> List[int]:
    if not numbers:
        return []

    rolling_max_list = []
    window_max = float('-inf')

    for i in range(len(numbers)):
        window_max = max(window_max, numbers[i])
        rolling_max_list.append(window_max)

    return rolling_max_list

