    planet_orbits = {planet: index for index, planet in enumerate(planets)}

    if planet1 not in planet_orbits or planet2 not in planet_orbits:
        return ()

    start = min(planet_orbits[planet1], planet_orbits[planet2])
    end = max(planet_orbits[planet1], planet_orbits[planet2])

    result = [planet for planet in planets[start+1:end] if planet != planet1 and planet != planet2]

    return tuple(sorted(result, key=lambda x: planet_orbits[x]))

# Test cases
