def do_algebra(operator, operand):
    if len(operator) != len(operand) - 1:
        return "Error: Length of operator list should be one less than the length of operand list"

    result = operand[0]
    for i in range(1, len(operand)):
        if operator[i-1] == '+':
            result += operand[i]
        elif operator[i-1] == '-':
            result -= operand[i]
        elif operator[i-1] == '*':
            result *= operand[i]
        elif operator[i-1] == '//':
            result //= operand[i]
        elif operator[i-1] == '**':
            result **= operand[i]

    return result

