def modp(n: int, p: int):
    def calculate_power_of_2(n):
        return 2 ** n

    def calculate_modulo(num, mod):
        return num % mod

    if n == 0:
        return 1
    elif p == 1:
        return 0
    else:
        power_of_2 = calculate_power_of_2(n)
        return calculate_modulo(power_of_2, p)

