def hex_key(num):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    def hex_to_decimal(hex_digit):
        if hex_digit.isdigit():
            return int(hex_digit)
        else:
            return ord(hex_digit) - ord('A') + 10

    prime_digits = {'2', '3', '5', '7', 'B', 'D'}
    count = 0
    for digit in num:
        decimal_value = hex_to_decimal(digit)
        if str(decimal_value) in prime_digits:
            count += 1

    return count

